+document.addEventListener('DOMContentLoaded', function() {
+    const form = document.getElementById('preferences-form');
+    const feedbackElement = document.getElementById('form-feedback');
+
+    form.addEventListener('submit', function(event) {
+        event.preventDefault();
+
+        const selectedOption = document.querySelector('input[name="notification_preference"]:checked');
+
+        if (selectedOption) {
+            const selectedValue = selectedOption.value;
+            const optionLabels = {
+                email: 'Email',
+                sms: 'SMS',
+                push: 'Push Notifications'
+            };
+
+            showFeedback(
+                `Success! You've selected ${optionLabels[selectedValue]} as your notification preference.`,
+                'success'
+            );
+
+            console.log('Form submitted with preference:', selectedValue);
+        } else {
+            showFeedback(
+                'Error: Please select a notification preference before submitting.',
+                'error'
+            );
+        }
+    });
+
+    function showFeedback(message, type) {
+        feedbackElement.textContent = message;
+        feedbackElement.className = `form-feedback ${type}`;
+
+        feedbackElement.focus();
+
+        if (type === 'success') {
+            setTimeout(function() {
+                feedbackElement.className = 'form-feedback';
+                feedbackElement.textContent = '';
+            }, 5000);
+        }
+    }
+
+    document.querySelectorAll('input[name="notification_preference"]').forEach(radio => {
+        radio.addEventListener('change', function() {
+            feedbackElement.className = 'form-feedback';
+            feedbackElement.textContent = '';
+        });
+    });
+});
+
