 input[type="radio"] {
     flex-shrink: 0;
     width: 1.25rem;
     height: 1.25rem;
     margin-top: 0.125rem;
     cursor: pointer;
     accent-color: var(--color-primary);
 }

 input[type="radio"]:checked {
     background-color: var(--color-primary);
 }

 .radio-option label {
     margin: 0;
     font-weight: 500;
     color: var(--color-text);
     cursor: pointer;
     flex: 1;
