const fs = require("fs");
const path = require("path");
const axeSource = require("fs").readFileSync(require.resolve("axe-core/axe.min.js"), "utf-8");

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const htmlPath = path.join(__dirname, "index.html");
  const htmlContent = fs.readFileSync(htmlPath, "utf-8");

  await page.setContent(htmlContent, { waitUntil: "load" });

  // Inject axe-core from node_modules
  await page.addInitScript(axeSource);

  // Simulate keyboard interaction
  await page.focus('input[name="notification_preference"]');
  await page.keyboard.press("ArrowDown");
  await page.click('button[type="submit"]');
  await page.waitForTimeout(500);

  const results = await page.evaluate(() => window.axe.run());
  await browser.close();

  const wcag = results.violations.filter(v => !v.tags.includes("best-practice"));
  const bp = results.violations.filter(v => v.tags.includes("best-practice"));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({
      id: v.id,
      impact: v.impact,
      description: v.description,
      targets: v.nodes.map(n => n.target)
    })),
    bp: bp.map(v => ({
      id: v.id,
      targets: v.nodes.map(n => n.target)
    })),
    passedTests: results.passes.length
  }, null, 2));

  process.exit(wcag.length > 0 ? 1 : 0);
})();

