const { chromium } = require("playwright");
const fs = require("fs");
const path = require("path");
const axeSource = require("fs").readFileSync(require.resolve("axe-core/axe.min.js"), "utf-8");

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const htmlPath = path.join(__dirname, "index.html");
  const fileUrl = `file://${htmlPath}`;

  await page.goto(fileUrl, { waitUntil: "load" });

  await page.evaluate((source) => {
    const script = document.createElement('script');
    script.textContent = source;
    document.head.appendChild(script);
  }, axeSource);

  await page.waitForFunction(() => typeof window.axe !== 'undefined', { timeout: 5000 });

  await page.focus('input[name="notification_preference"]');
  await page.keyboard.press("ArrowDown");
  await page.click('button[type="submit"]');
  await page.waitForTimeout(500);

  const results = await page.evaluate(() => window.axe.run());
  await browser.close();

  const wcag = results.violations.filter(v => !v.tags.includes("best-practice"));

  console.log("=== ACCESSIBILITY TEST RESULTS ===");
  console.log(`WCAG Violations: ${wcag.length}`);
  console.log(`Best Practice Warnings: ${results.violations.filter(v => v.tags.includes("best-practice")).length}`);
  console.log(`Passed Checks: ${results.passes.length}`);

  if (wcag.length === 0) {
    console.log("\n✓ All WCAG 2.2 AA requirements met!");
  } else {
    wcag.forEach(v => {
      console.log(`\n✗ ${v.id} (${v.impact}): ${v.description}`);
      v.nodes.forEach(n => console.log(`  - ${n.target}`));
    });
  }

  process.exit(wcag.length > 0 ? 1 : 0);
})();
